import{_ as e,o as a,c as i,an as l}from"./chunks/framework.CfibuiLs.js";const c=JSON.parse('{"title":"Signal Example — ICA 3: Mixing & Unmixing","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/teaching/ica/signal_example_ica_separation.md","filePath":"tutorials/teaching/ica/signal_example_ica_separation.md","lastUpdated":null}'),o={name:"tutorials/teaching/ica/signal_example_ica_separation.md"};function n(s,t,r,h,d,g){return a(),i("div",null,[...t[0]||(t[0]=[l(`<h1 id="Signal-Example-—-ICA-3:-Mixing-and-Unmixing" tabindex="-1">Signal Example — ICA 3: Mixing &amp; Unmixing <a class="header-anchor" href="#Signal-Example-—-ICA-3:-Mixing-and-Unmixing" aria-label="Permalink to &quot;Signal Example — ICA 3: Mixing &amp; Unmixing {#Signal-Example-—-ICA-3:-Mixing-and-Unmixing}&quot;">​</a></h1><p>Interactive demonstration of <strong>signal mixing and ICA unmixing</strong>.</p><h2 id="The-Cocktail-Party-Problem" tabindex="-1">The Cocktail Party Problem <a class="header-anchor" href="#The-Cocktail-Party-Problem" aria-label="Permalink to &quot;The Cocktail Party Problem {#The-Cocktail-Party-Problem}&quot;">​</a></h2><p>Imagine you&#39;re at a party with two people talking. You have two microphones, but each one picks up <em>both</em> voices — just at different volumes depending on how close each person is to each mic.</p><p>That&#39;s exactly what happens with EEG:</p><ul><li><p>Your <strong>brain</strong> generates an electrical signal</p></li><li><p>Your <strong>eyes</strong> produce large signal changes every time you blink</p></li><li><p>Each <strong>electrode</strong> on your scalp picks up a <em>mixture</em> of both</p></li></ul><p>The result? Every electrode&#39;s recording is a jumbled combination of brain activity and blink artifacts. You never see the clean sources directly.</p><p><strong>ICA</strong> (Independent Component Analysis) is the algorithm that untangles the mixture back into the original sources — like being able to isolate each person&#39;s voice from the party recording.</p><h2 id="What-This-Demo-Shows" tabindex="-1">What This Demo Shows <a class="header-anchor" href="#What-This-Demo-Shows" aria-label="Permalink to &quot;What This Demo Shows {#What-This-Demo-Shows}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Column</th><th style="text-align:left;">What you see</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Left — &quot;What&#39;s really happening&quot;</strong></td><td style="text-align:left;">The two true source signals: a brain oscillation and eye blink artifacts</td></tr><tr><td style="text-align:left;"><strong>Middle — &quot;What electrodes record&quot;</strong></td><td style="text-align:left;">The mixed signals, with the mixing equation shown in the title (e.g. <code>E1 = 1.00 × Brain + 0.50 × Blink</code>)</td></tr><tr><td style="text-align:left;"><strong>Right — &quot;What ICA recovers&quot;</strong></td><td style="text-align:left;">The unmixed signals recovered by ICA</td></tr></tbody></table><p>Below the plots, three panels show the <strong>Matrix Equations</strong>:</p><ol><li><p><strong>Mixing M</strong>: How sources <code>S</code> become electrodes <code>E</code> (<code>M × S = E</code>).</p></li><li><p><strong>Exact Inverse M⁻¹</strong>: The mathematically perfect &quot;reverse recipe&quot;.</p></li><li><p><strong>Your Weights / ICA Found</strong>: The current unmixing recipe being applied.</p></li></ol><h2 id="Things-to-Try" tabindex="-1">Things to Try <a class="header-anchor" href="#Things-to-Try" aria-label="Permalink to &quot;Things to Try {#Things-to-Try}&quot;">​</a></h2><h3 id="Step-1:-See-the-Problem" tabindex="-1">Step 1: See the Problem <a class="header-anchor" href="#Step-1:-See-the-Problem" aria-label="Permalink to &quot;Step 1: See the Problem {#Step-1:-See-the-Problem}&quot;">​</a></h3><ol><li><p>Set <strong>Mix Amount</strong> to 0.5. Look at the middle column — the blink spikes are now mixed into the brain electrode (E1), and brain oscillations contaminate the blink electrode (E2).</p></li><li><p>Look at the <strong>Mixing M</strong> panel. It&#39;s a colored 2×2 grid showing exactly how much each source bleeds into each electrode.</p></li></ol><h3 id="Step-2:-Try-to-Fix-It-Yourself" tabindex="-1">Step 2: Try to Fix It Yourself <a class="header-anchor" href="#Step-2:-Try-to-Fix-It-Yourself" aria-label="Permalink to &quot;Step 2: Try to Fix It Yourself {#Step-2:-Try-to-Fix-It-Yourself}&quot;">​</a></h3><ol><li><p>Use the <strong>&quot;Subtract E2 from E1&quot;</strong> slider. You&#39;re trying to remove the blink contamination from electrode 1 by subtracting a scaled version of electrode 2.</p></li><li><p>Watch the <strong>Shape Match</strong> — can you get to 100%? It&#39;s surprisingly hard!</p></li><li><p>Notice that even if you get 100% Shape, the <strong>Amplitude Match</strong> might be low. This is because a simple subtraction doesn&#39;t correctly invert the whole mixing matrix.</p></li></ol><h3 id="Step-3:-Let-ICA-Do-It" tabindex="-1">Step 3: Let ICA Do It <a class="header-anchor" href="#Step-3:-Let-ICA-Do-It" aria-label="Permalink to &quot;Step 3: Let ICA Do It {#Step-3:-Let-ICA-Do-It}&quot;">​</a></h3><ol><li><p>Click <strong>Unmix!</strong> — ICA finds the optimal 2×2 matrix automatically.</p></li><li><p>Watch the manual sliders <em>jump</em> to the values ICA found — now you can see exactly what weights it used.</p></li><li><p>Compare the <strong>ICA Found Matrix</strong> with the <strong>Exact Inverse M⁻¹</strong> — ICA essentially &quot;reverse engineered&quot; the mixing recipe without ever seeing the original sources!</p></li></ol><h2 id="Controls" tabindex="-1">Controls <a class="header-anchor" href="#Controls" aria-label="Permalink to &quot;Controls {#Controls}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Control</th><th style="text-align:left;">Range</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;">Mix Amount</td><td style="text-align:left;">0–1</td><td style="text-align:left;">How much the sources bleed across electrodes</td></tr><tr><td style="text-align:left;">Brain Freq</td><td style="text-align:left;">4–20 Hz</td><td style="text-align:left;">Frequency of the oscillatory brain signal</td></tr><tr><td style="text-align:left;">Blink Size</td><td style="text-align:left;">0.5–5</td><td style="text-align:left;">Amplitude of eye blink artifacts</td></tr><tr><td style="text-align:left;">Noise</td><td style="text-align:left;">0–1</td><td style="text-align:left;">Additive sensor noise</td></tr><tr><td style="text-align:left;">Subtract E2→E1</td><td style="text-align:left;">0–1.5</td><td style="text-align:left;">Manual unmixing: remove E2 contribution from E1</td></tr><tr><td style="text-align:left;">Subtract E1→E2</td><td style="text-align:left;">0–1.5</td><td style="text-align:left;">Manual unmixing: remove E1 contribution from E2</td></tr><tr><td style="text-align:left;">Unmix!</td><td style="text-align:left;">—</td><td style="text-align:left;">Run ICA to find optimal unmixing weights</td></tr><tr><td style="text-align:left;">Reset</td><td style="text-align:left;">—</td><td style="text-align:left;">Clear all unmixing</td></tr></tbody></table><h2 id="Why-Does-ICA-Work?" tabindex="-1">Why Does ICA Work? <a class="header-anchor" href="#Why-Does-ICA-Work?" aria-label="Permalink to &quot;Why Does ICA Work? {#Why-Does-ICA-Work?}&quot;">​</a></h2><p>ICA relies on one key insight: <strong>brain signals and eye blinks are statistically independent</strong> — knowing the state of one tells you nothing about the state of the other.</p><p>The Central Limit Theorem says that mixing independent, non-Gaussian sources always produces something <em>more</em> Gaussian (more random-looking) than either source alone. ICA exploits this in reverse: it searches for the unmixing matrix that makes the outputs <em>as non-Gaussian as possible</em> — which turns out to be equivalent to making them statistically independent.</p><div class="tip custom-block github-alert"><p class="custom-block-title">This demo shows that unmixing is just **Matrix Inversion** — see also [Part 4: ICA with Scatter Geometry](signal_example_ica_geometry.md).</p><p></p></div><h2 id="See-Also" tabindex="-1">See Also <a class="header-anchor" href="#See-Also" aria-label="Permalink to &quot;See Also {#See-Also}&quot;">​</a></h2><ul><li><p><a href="./signal_example_ica_math">Part 1: Matrix Math Basics</a> — Fundamental math prerequisites</p></li><li><p><a href="./signal_example_ica_mixture">Part 2: What Is a Mixture?</a> — Start here if you&#39;ve never seen ICA</p></li><li><p><a href="./signal_example_ica_geometry">Part 4: 3 Sources &amp; Scatter Geometry</a> — Advanced: rotation geometry, scatter plots, kurtosis</p></li><li><p><a href="./signal_example_ica_sphering">Part 5: Sphering (Whitening)</a> — Why ICA optimization is just finding an angle</p></li><li><p><a href="./signal_example_ica_optimization">Part 6: Inside the Black Box</a> — How the algorithm actually finds the sources</p></li><li><p><a href="./../../preprocessing/ica">ICA Demo</a> — Full ICA workflow on real EEG data</p></li><li><p><a href="./../signal_processing/signal_example_composition">Signal Example — Composition</a> — Building complex waveforms from sine waves</p></li><li><p><a href="https://eeglab.org/tutorials/06_RejectArtifacts/RunICA.html" target="_blank" rel="noreferrer">EEGLAB: Running ICA</a> — Practical guide to ICA in EEGLAB</p></li><li><p><a href="https://arnauddelorme.com/ica_for_dummies/" target="_blank" rel="noreferrer">ICA for Dummies</a> — Arnaud Delorme&#39;s accessible introduction to ICA</p></li></ul><h2 id="Code" tabindex="-1">Code <a class="header-anchor" href="#Code" aria-label="Permalink to &quot;Code {#Code}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> EegFun</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">EegFun</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">signal_example_ica_separation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div>`,29)])])}const m=e(o,[["render",n]]);export{c as __pageData,m as default};
